<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="description" content="Lake Music's living community archive, from 1970 to today.">
  <title>Lake Music — The Living Archive</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&display=swap');
    :root{--navy:#061e3b;--deep:#031329;--blue:#167ad5;--mist:#dceefa;--gold:#ffc21a;--paper:#fffdf7;--ink:#0a315b;--line:rgba(255,255,255,.22);--serif:'Instrument Serif',Georgia,serif;--sans:'DM Sans',Arial,sans-serif;--mono:'DM Mono',monospace}
    *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans)}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.nav{position:absolute;z-index:5;top:0;left:0;right:0;padding:24px clamp(20px,5vw,74px);display:flex;align-items:center;justify-content:space-between;color:white}.nav img{width:119px;filter:brightness(0) invert(1)}.nav-links{display:flex;align-items:center;gap:26px;font-size:.76rem;letter-spacing:.12em;text-transform:uppercase;font-weight:700}.nav-links a:hover{color:var(--gold)}.nav-links .share-link{border:1px solid rgba(255,255,255,.55);padding:10px 15px;border-radius:999px}
    .hero{min-height:100svh;display:flex;align-items:end;position:relative;isolation:isolate;overflow:hidden;color:white}.hero::before{content:"";position:absolute;z-index:-2;inset:0;background:url('assets/lake-music-street.png') center/cover}.hero::after{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(90deg,rgba(1,18,40,.95) 0%,rgba(1,18,40,.79) 37%,rgba(1,18,40,.21) 72%,rgba(1,18,40,.28)),linear-gradient(0deg,rgba(1,18,40,.76),transparent 46%)}.hero-content{width:min(1220px,100%);padding:0 clamp(20px,5vw,74px) clamp(58px,9vh,108px);margin:auto}.eyebrow{display:flex;align-items:center;gap:10px;color:var(--gold);font:500 .72rem var(--mono);letter-spacing:.14em;text-transform:uppercase}.eyebrow::before{content:"";height:1px;width:32px;background:currentColor}.hero h1{font:400 clamp(4.6rem,10vw,9.4rem)/.82 var(--serif);letter-spacing:-.06em;max-width:780px;margin:23px 0 29px;text-shadow:0 8px 30px rgba(0,0,0,.25)}.hero h1 em{font-style:italic;color:var(--gold)}.hero-copy{max-width:500px;font-size:1.07rem;line-height:1.65;padding-left:20px;border-left:2px solid var(--gold);color:#f1f8ff}.button-row{display:flex;gap:12px;flex-wrap:wrap;margin-top:31px}.button{border:0;border-radius:999px;padding:14px 20px;font-weight:700;cursor:pointer;display:inline-flex;gap:8px;align-items:center;transition:transform .25s,box-shadow .25s}.button:hover{transform:translateY(-3px)}.button.primary{background:var(--gold);color:var(--navy);box-shadow:0 9px 25px rgba(255,194,26,.22)}.button.ghost{background:rgba(255,255,255,.08);color:white;border:1px solid rgba(255,255,255,.45);backdrop-filter:blur(5px)}.hero-stat{position:absolute;right:clamp(20px,5vw,74px);bottom:48px;text-align:right;color:#eff7ff}.hero-stat b{display:block;font:400 4rem/.8 var(--serif);color:var(--gold)}.hero-stat span{font:.68rem var(--mono);letter-spacing:.13em;text-transform:uppercase}.scroll-cue{position:absolute;left:clamp(20px,5vw,74px);bottom:28px;font:.63rem var(--mono);letter-spacing:.12em;text-transform:uppercase;opacity:.7}.scroll-cue i{display:inline-block;height:24px;border-left:1px solid var(--gold);margin:0 0 -8px 9px;animation:cue 1.5s infinite}@keyframes cue{50%{transform:scaleY(.4);transform-origin:top}}
    .intro{padding:clamp(80px,12vw,145px) clamp(20px,5vw,74px);background:linear-gradient(115deg,#fffdf7,#e9f5fc)}.intro-inner{max-width:1180px;margin:auto;display:grid;grid-template-columns:.82fr 1.18fr;gap:clamp(34px,8vw,130px);align-items:end}.section-label{font:500 .71rem var(--mono);letter-spacing:.15em;text-transform:uppercase;color:#5d83a5}.intro h2{font:400 clamp(3rem,6vw,5.5rem)/.92 var(--serif);letter-spacing:-.05em;margin:15px 0 0}.intro h2 em{font-style:italic;color:var(--blue)}.intro p{font-size:1.12rem;line-height:1.7;color:#426584;max-width:540px;margin:0}.intro-note{margin-top:21px;padding:16px 19px;border-left:2px solid var(--gold);background:rgba(255,255,255,.74);font-size:.88rem;line-height:1.55;color:#365e82}
    .archive{position:relative;background:radial-gradient(ellipse at 50% 30%,#125e9e 0%,var(--navy) 48%,var(--deep) 100%);color:#f6fbff;padding:clamp(78px,10vw,130px) clamp(20px,5vw,74px) clamp(90px,12vw,160px);overflow:hidden}.archive::before{content:"";position:absolute;inset:0;opacity:.13;background:linear-gradient(115deg,transparent 0 47%,#63b5ee 48% 49%,transparent 50% 100%),repeating-linear-gradient(90deg,transparent 0 6.4%,rgba(255,255,255,.2) 6.45% 6.5%);pointer-events:none}.archive-inner{max-width:1220px;margin:auto;position:relative}.archive-heading{display:flex;justify-content:space-between;align-items:end;gap:30px}.archive-heading h2{font:400 clamp(3.2rem,6.6vw,6.7rem)/.85 var(--serif);letter-spacing:-.06em;margin:17px 0 0}.archive-heading h2 em{color:var(--gold);font-style:italic}.archive-heading p{max-width:335px;color:#b8d4e9;line-height:1.6;margin:0}.year-readout{text-align:right}.year-readout strong{display:block;font:400 clamp(4rem,9vw,8rem)/.72 var(--serif);color:var(--gold);letter-spacing:-.06em;transition:opacity .2s,transform .2s}.year-readout span{font:.68rem var(--mono);letter-spacing:.14em;text-transform:uppercase;color:#cbe1f1}.timeline-control{margin-top:66px;position:relative}.track-shell{position:relative;padding:0 5px}.range{appearance:none;width:100%;height:3px;border-radius:10px;background:linear-gradient(90deg,var(--gold) var(--progress,50%),rgba(255,255,255,.26) var(--progress,50%));outline:none;cursor:pointer}.range::-webkit-slider-thumb{appearance:none;width:22px;height:22px;border-radius:50%;background:var(--gold);border:5px solid var(--deep);box-shadow:0 0 0 2px var(--gold),0 0 25px rgba(255,194,26,.65)}.range::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:var(--gold);border:5px solid var(--deep);box-shadow:0 0 0 2px var(--gold)}.year-markers{height:56px;position:relative}.year-marker{position:absolute;top:0;transform:translateX(-50%);color:#b9d7ec;background:transparent;border:0;padding:12px 3px;cursor:pointer;font:.68rem var(--mono);transition:color .2s,transform .2s}.year-marker::before{content:"";position:absolute;top:0;left:50%;height:8px;border-left:1px solid rgba(255,255,255,.55)}.year-marker:hover,.year-marker.active{color:var(--gold);transform:translateX(-50%) translateY(-3px)}.year-marker.active::before{height:15px;border-color:var(--gold)}.memory-count{font:.68rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:#b9d7ec;margin:5px 0 14px}.memory-stage{min-height:365px;position:relative}.memory-empty{min-height:310px;display:flex;align-items:center;justify-content:center;border:1px dashed rgba(255,255,255,.28);color:#b9d7ec;text-align:center;font:400 1.4rem/1.4 var(--serif);padding:35px}.memory-rail{display:flex;gap:18px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-color:var(--gold) rgba(255,255,255,.12);scrollbar-width:thin;padding:1px 1px 18px}.memory-rail::-webkit-scrollbar{height:5px}.memory-rail::-webkit-scrollbar-track{background:rgba(255,255,255,.12)}.memory-rail::-webkit-scrollbar-thumb{background:var(--gold);border-radius:4px}.memory-card{flex:0 0 min(84%,460px);min-height:315px;display:grid;grid-template-columns:42% 58%;scroll-snap-align:start;background:#f8fbff;color:var(--navy);box-shadow:0 20px 45px rgba(0,0,0,.22);animation:enter .55s both}.memory-card:nth-child(2){animation-delay:.08s}.memory-card:nth-child(3){animation-delay:.16s}.memory-media{position:relative;overflow:hidden;background:#c6d8e4}.memory-media img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .6s}.memory-card:hover .memory-media img{transform:scale(1.06)}.memory-photo-count{position:absolute;bottom:13px;left:13px;border-radius:999px;padding:6px 8px;color:white;background:rgba(3,19,41,.72);font:.62rem var(--mono);letter-spacing:.06em}.memory-body{padding:30px 28px;display:flex;flex-direction:column}.memory-meta{font:.65rem var(--mono);letter-spacing:.11em;text-transform:uppercase;color:#5d7d99}.memory-body blockquote{font:400 1.24rem/1.4 var(--serif);margin:20px 0;color:#153d68}.memory-byline{margin-top:auto;font-size:.76rem;font-weight:700;color:#35658d}.rail-controls{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.circle-button{width:39px;height:39px;border:1px solid rgba(255,255,255,.42);border-radius:50%;background:rgba(255,255,255,.08);color:white;cursor:pointer;transition:background .2s,transform .2s}.circle-button:hover{background:var(--gold);color:var(--navy);transform:translateY(-2px)}@keyframes enter{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
    .contribute{background:#edf7fc;padding:clamp(80px,11vw,135px) clamp(20px,5vw,74px)}.contribute-grid{max-width:1180px;margin:auto;display:grid;grid-template-columns:.75fr 1.25fr;gap:clamp(36px,9vw,130px);align-items:start}.contribute h2{font:400 clamp(3rem,5.8vw,5.6rem)/.9 var(--serif);letter-spacing:-.05em;margin:15px 0}.contribute h2 em{font-style:italic;color:var(--blue)}.contribute-copy{color:#4e6e88;line-height:1.7}.form{background:white;padding:clamp(24px,4vw,47px);border-top:3px solid var(--gold);box-shadow:18px 18px 0 var(--navy),0 15px 50px rgba(13,58,97,.1)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.field{display:grid;gap:7px;margin-bottom:17px}.field label{font:.68rem var(--mono);letter-spacing:.12em;text-transform:uppercase;color:#476b87}.field input,.field select,.field textarea{width:100%;border:1px solid #bdd3e3;background:#fbfdff;color:var(--navy);padding:12px;border-radius:2px;outline-color:var(--blue)}.field textarea{min-height:124px;resize:vertical}.form-helper{font-size:.74rem;color:#668299;text-align:right;margin-top:-10px}.upload{border:1px dashed #8eb1ca;padding:13px;display:flex;justify-content:space-between;align-items:center;gap:15px;color:#3e6d93;font-size:.88rem;cursor:pointer}.upload input{position:absolute;width:1px;height:1px;opacity:0}.upload small{color:#6f879a}.preview{display:flex;gap:7px;min-height:0;margin-top:11px}.preview img{width:62px;height:47px;object-fit:cover;border:1px solid #bcd0dd}.form-status{min-height:22px;margin:15px 0 0;color:#236b4f;font-size:.88rem}.form-status.error{color:#ae3933}.form .button{background:var(--blue);color:white}.community-promise{margin-top:29px;padding-top:21px;border-top:1px solid #c8deeb;font-size:.85rem;line-height:1.55;color:#55748e}
    footer{background:var(--deep);color:#c7ddeb;padding:28px clamp(20px,5vw,74px);display:flex;align-items:center;justify-content:space-between;gap:25px;flex-wrap:wrap;font-size:.8rem}footer img{width:103px;filter:brightness(0) invert(1)}footer div{display:flex;gap:20px;flex-wrap:wrap}@media(max-width:800px){.nav-links a:not(.share-link){display:none}.hero-stat{display:none}.intro-inner,.contribute-grid{grid-template-columns:1fr}.archive-heading{align-items:start;flex-direction:column}.year-readout{text-align:left}.memory-card{flex-basis:92%;grid-template-columns:1fr;min-height:450px}.memory-media{min-height:190px}.memory-body{min-height:230px}.form-grid{grid-template-columns:1fr}.nav{padding-top:18px}.hero h1{font-size:clamp(4rem,18vw,6.2rem)}.scroll-cue{display:none}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
    .memory-media img:not(:first-child){position:absolute;width:48%;height:37%;right:12px;bottom:12px;border:3px solid white;box-shadow:0 8px 18px rgba(0,0,0,.24)}.memory-card:hover .memory-media img:not(:first-child){transform:scale(1.02)}
  </style>
</head>
<body>
  <header class="nav"><a href="#top"><img src="assets/logo.png" alt="Lake Music"></a><nav class="nav-links"><a href="#archive">The archive</a><a href="#contribute">Share a memory</a><a class="share-link" href="#contribute">Add your chapter</a></nav></header>
  <main id="top">
    <section class="hero"><div class="hero-content"><p class="eyebrow">Lake Oswego, Oregon · Est. 1970</p><h1>The music we <em>remember</em> together.</h1><p class="hero-copy">A living archive of first lessons, beloved instruments, family traditions, and the community that has grown around Lake Music for 56 years.</p><div class="button-row"><a class="button primary" href="#archive">Enter the archive <span>→</span></a><a class="button ghost" href="#contribute">Share your story</a></div></div><div class="hero-stat"><b>56</b><span>Years of community</span></div><span class="scroll-cue">Scroll to explore <i></i></span></section>
    <section class="intro"><div class="intro-inner"><div><p class="section-label">One store. Many generations.</p><h2>Every family has a <em>first note.</em></h2></div><div><p>Maybe your grandfather found his first guitar here. Maybe you took cello lessons in 1999 and now your daughter is discovering her own instrument. This is the place to keep those chapters together.</p><p class="intro-note">Move through the timeline below to see community memories from a specific year. Each submitted story becomes part of the archive at the year it happened.</p></div></div></section>
    <section class="archive" id="archive"><div class="archive-inner"><div class="archive-heading"><div><p class="section-label" style="color:var(--gold)">The Lake Music living archive</p><h2>Choose a year.<br><em>Meet its memories.</em></h2></div><div class="year-readout"><strong id="yearReadout">1999</strong><span id="yearDescriptor">A year in the Lake Music story</span></div></div><div class="timeline-control"><div class="track-shell"><input class="range" id="yearRange" type="range" min="1970" max="2026" value="1999" aria-label="Choose a year in the Lake Music archive"><div class="year-markers" id="yearMarkers" aria-label="Years with shared stories"></div></div></div><p class="memory-count" id="memoryCount"></p><div class="memory-stage" id="memoryStage"></div><div class="rail-controls"><button class="circle-button" id="railPrevious" type="button" aria-label="Show previous memory">←</button><button class="circle-button" id="railNext" type="button" aria-label="Show next memory">→</button></div></div></section>
    <section class="contribute" id="contribute"><div class="contribute-grid"><div><p class="section-label">Add your chapter</p><h2>Your relationship with <em>Lake Music</em> belongs here.</h2><p class="contribute-copy">Share the instrument, lesson, recital, repair, or family tradition that connects you to Lake Music. Your story will be placed on its year in this living archive.</p><p class="community-promise">Stories are designed for moderation before public publishing on the main website. This page demonstrates the client-side archive experience.</p></div><form class="form" id="storyForm"><div class="form-grid"><div class="field"><label for="name">Your name</label><input id="name" name="name" required placeholder="e.g. Jamie R."></div><div class="field"><label for="year">Memory year</label><input id="year" name="year" required inputmode="numeric" min="1970" max="2026" placeholder="e.g. 1999"></div></div><div class="field"><label for="memoryType">What does it celebrate?</label><select id="memoryType" name="memoryType"><option>First music lesson</option><option>Instrument purchase or rental</option><option>Concert, recital, or competition</option><option>Family tradition</option><option>Another Lake Music memory</option></select></div><div class="field"><label for="storyText">Your story</label><textarea id="storyText" name="storyText" maxlength="500" required placeholder="Tell us what Lake Music has meant to you."></textarea><span class="form-helper"><span id="charCount">0</span>/500</span></div><label class="upload" for="photos"><span>＋ Add up to two photos</span><small id="photoLabel">Optional · JPG, PNG, or WebP</small><input id="photos" name="photos" type="file" accept="image/*" multiple></label><div class="preview" id="preview" aria-live="polite"></div><div class="button-row"><button class="button" type="submit">Add to the archive <span>→</span></button></div><p class="form-status" id="formStatus" role="status"></p></form></div></section>
  </main>
  <footer><img src="assets/logo.png" alt="Lake Music"><div><span>Lake Oswego, OR</span><span>Est. 1970</span><a href="#contribute">Share a memory</a></div><span>© Lake Music</span></footer>
  <script>
    const data=[
      {year:1974,name:'Sample family memory',type:'First instrument',text:'My grandfather brought home his first guitar from Lake Music. Decades later, it is still the instrument everyone asks about when our family gathers.',images:['assets/guitars.jpg']},
      {year:1989,name:'Sample customer memory',type:'Instrument purchase',text:'I bought my first instrument here in 1989. Thirty-six years later, I still think of that afternoon whenever I open its case.',images:['assets/instruments.jpg']},
      {year:1999,name:'Sample student memory',type:'First music lesson',text:'I took my first cello lessons at Lake Music in 1999. The lesson room felt huge then; now I am sending my daughter to find her first instrument.',images:['assets/first-lesson.jpg','assets/student.jpg']},
      {year:1999,name:'Sample family memory',type:'Family tradition',text:'The same store that helped my dad choose a guitar helped me find mine. We compare notes about both visits every time we play together.',images:['assets/guitars.jpg']},
      {year:2004,name:'Sample recital memory',type:'Local performance',text:'The recital was the first time our child played for an audience. The walk out of Lake Music afterward felt like a standing ovation all its own.',images:['assets/event.jpg','assets/community.jpg']},
      {year:2011,name:'Sample community memory',type:'Lesson room memory',text:'A new bow, a patient teacher, and one more small step forward. Lake Music made every early mistake feel like part of the music.',images:['assets/community.jpg']},
      {year:2017,name:'Sample student memory',type:'First music lesson',text:'We came in nervous and left with a violin, a case, and the confidence to begin. That first day still feels like the opening measure.',images:['assets/student.jpg']},
      {year:2023,name:'Sample community memory',type:'Family tradition',text:'Our family now has three generations with Lake Music stories. It has stayed part of the neighborhood soundtrack through every chapter.',images:['assets/shop.jpg']}
    ];
    const range=document.getElementById('yearRange'),readout=document.getElementById('yearReadout'),descriptor=document.getElementById('yearDescriptor'),markers=document.getElementById('yearMarkers'),stage=document.getElementById('memoryStage'),count=document.getElementById('memoryCount'),previous=document.getElementById('railPrevious'),next=document.getElementById('railNext');
    const clean=value=>String(value).replace(/[<>]/g,'');
    function storyYears(){return [...new Set(data.map(item=>item.year))].sort((a,b)=>a-b)}
    function percent(year){return ((year-1970)/56)*100}
    function drawMarkers(){markers.innerHTML='';storyYears().forEach(year=>{const button=document.createElement('button');button.type='button';button.className='year-marker';button.style.left=`${percent(year)}%`;button.textContent=year;button.dataset.year=year;button.addEventListener('click',()=>{range.value=year;renderYear(year)});markers.append(button)})}
    function storyCard(story){const photos=story.images.map(image=>`<img src="${image}" alt="Story image for ${clean(story.name)}">`).join('');return `<article class="memory-card"><div class="memory-media">${photos}<span class="memory-photo-count">${story.images.length} photo${story.images.length>1?'s':''}</span></div><div class="memory-body"><span class="memory-meta">${story.year} · ${clean(story.type)}</span><blockquote>“${clean(story.text)}”</blockquote><span class="memory-byline">${clean(story.name)}</span></div></article>`}
    function renderYear(year){const matches=data.filter(story=>story.year===Number(year));readout.textContent=year;readout.animate([{opacity:.25,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,easing:'ease-out'});const progress=percent(year);range.style.setProperty('--progress',`${progress}%`);[...markers.children].forEach(marker=>marker.classList.toggle('active',Number(marker.dataset.year)===Number(year)));descriptor.textContent=matches.length?`${matches.length} shared ${matches.length===1?'memory':'memories'} from this year`:'A year in the Lake Music story';count.textContent=matches.length?`${matches.length} community ${matches.length===1?'story':'stories'} · use the arrows or scroll to explore`:'No shared stories for this year yet';stage.innerHTML=matches.length?`<div class="memory-rail" id="memoryRail">${matches.map(storyCard).join('')}</div>`:'<div class="memory-empty">This year is ready for its first Lake Music story.<br>Was it yours?</div>'}
    range.addEventListener('input',()=>renderYear(range.value));previous.addEventListener('click',()=>document.getElementById('memoryRail')?.scrollBy({left:-390,behavior:'smooth'}));next.addEventListener('click',()=>document.getElementById('memoryRail')?.scrollBy({left:390,behavior:'smooth'}));drawMarkers();renderYear(range.value);
    const form=document.getElementById('storyForm'),text=document.getElementById('storyText'),charCount=document.getElementById('charCount'),photos=document.getElementById('photos'),photoLabel=document.getElementById('photoLabel'),preview=document.getElementById('preview'),status=document.getElementById('formStatus');text.addEventListener('input',()=>charCount.textContent=text.value.length);photos.addEventListener('change',()=>{const files=[...photos.files];if(files.length>2||files.some(file=>!file.type.startsWith('image/'))){status.textContent='Please choose no more than two image files.';status.classList.add('error');photos.value='';preview.innerHTML='';return}status.textContent='';status.classList.remove('error');photoLabel.textContent=files.length?`${files.length} image${files.length>1?'s':''} selected`:'Optional · JPG, PNG, or WebP';preview.innerHTML=files.map(file=>`<img src="${URL.createObjectURL(file)}" alt="Selected story image">`).join('')});form.addEventListener('submit',event=>{event.preventDefault();const formData=new FormData(form),year=Number(formData.get('year')),files=[...photos.files];if(!Number.isInteger(year)||year<1970||year>2026){status.textContent='Please use a year from 1970 to 2026.';status.classList.add('error');return}const story={year,name:clean(formData.get('name').trim()),type:clean(formData.get('memoryType')),text:clean(formData.get('storyText').trim()),images:files.map(file=>URL.createObjectURL(file))};if(!story.text){status.textContent='Please add your story before submitting.';status.classList.add('error');return}if(!story.images.length)story.images=['assets/community.jpg'];data.push(story);drawMarkers();range.value=year;renderYear(year);status.textContent=`Thank you, ${story.name}. Your story is now shown in the ${year} archive.`;status.classList.remove('error');form.reset();charCount.textContent='0';photoLabel.textContent='Optional · JPG, PNG, or WebP';preview.innerHTML='';document.getElementById('archive').scrollIntoView({behavior:'smooth',block:'start'})});
  </script>
</body>
</html>
